CREATE SCHEMA IF NOT EXISTS water_q7; SET search_path TO water_q7,public;
CREATE TABLE IF NOT EXISTS customers(customer_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,full_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS readings(reading_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id INT NOT NULL REFERENCES customers,reading_month DATE NOT NULL CHECK(EXTRACT(DAY FROM reading_month)=1),previous_reading NUMERIC(12,2) NOT NULL CHECK(previous_reading>=0),current_reading NUMERIC(12,2) NOT NULL CHECK(current_reading>=0),UNIQUE(customer_id,reading_month));
CREATE TABLE IF NOT EXISTS bills(bill_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reading_id BIGINT NOT NULL UNIQUE REFERENCES readings,charge NUMERIC(12,2) NOT NULL,amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0,due_on DATE NOT NULL,CHECK(amount_paid>=0 AND amount_paid<=charge));
CREATE TABLE IF NOT EXISTS receivable_snapshot(snapshot_date DATE PRIMARY KEY,total_due NUMERIC(14,2) NOT NULL);
INSERT INTO customers VALUES(1,'Customer One'),(2,'Customer Two'),(3,'Customer Three') ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION fn_water_charge(p_units NUMERIC) RETURNS NUMERIC(12,2) LANGUAGE plpgsql AS $$
BEGIN IF p_units IS NULL OR p_units<0 THEN RAISE EXCEPTION 'Consumption cannot be NULL or negative'; END IF; RETURN round(LEAST(p_units,10)*5+GREATEST(p_units-10,0)*8,2); END $$;
CREATE OR REPLACE FUNCTION fn_validate_reading() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.current_reading<NEW.previous_reading THEN RAISE EXCEPTION 'Current reading cannot be below previous reading'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_validate_reading ON readings;
CREATE TRIGGER trg_validate_reading BEFORE INSERT OR UPDATE ON readings FOR EACH ROW EXECUTE FUNCTION fn_validate_reading();
CREATE OR REPLACE PROCEDURE pr_generate_bill(p_reading_id BIGINT,p_due_on DATE) LANGUAGE plpgsql AS $$
DECLARE u NUMERIC; BEGIN SELECT current_reading-previous_reading INTO u FROM readings WHERE reading_id=p_reading_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown reading'; END IF; IF p_due_on IS NULL THEN RAISE EXCEPTION 'Due date required'; END IF; INSERT INTO bills(reading_id,charge,amount_paid,due_on) VALUES(p_reading_id,fn_water_charge(u),0,p_due_on); END $$;
INSERT INTO readings(reading_id,customer_id,reading_month,previous_reading,current_reading) VALUES(1,1,date_trunc('month',CURRENT_DATE)::date-interval '2 months',10,10),(2,2,date_trunc('month',CURRENT_DATE)::date-interval '2 months',0,10),(3,3,date_trunc('month',CURRENT_DATE)::date-interval '2 months',20,35),(4,1,date_trunc('month',CURRENT_DATE)::date-interval '1 month',10,18),(5,2,date_trunc('month',CURRENT_DATE)::date-interval '1 month',10,25),(6,3,date_trunc('month',CURRENT_DATE)::date-interval '1 month',35,40) ON CONFLICT DO NOTHING;
CALL pr_generate_bill(1,CURRENT_DATE-10); CALL pr_generate_bill(2,CURRENT_DATE-10); CALL pr_generate_bill(3,CURRENT_DATE-10); CALL pr_generate_bill(4,CURRENT_DATE+10); CALL pr_generate_bill(5,CURRENT_DATE+10); CALL pr_generate_bill(6,CURRENT_DATE+10);
CREATE OR REPLACE VIEW v_overdue_bills AS SELECT c.full_name,b.due_on,b.charge-b.amount_paid AS outstanding_amount FROM bills b JOIN readings r USING(reading_id) JOIN customers c USING(customer_id) WHERE b.due_on<CURRENT_DATE AND b.amount_paid<b.charge;
CREATE INDEX IF NOT EXISTS ix_bills_due_unpaid ON bills(due_on) WHERE amount_paid<charge;
EXPLAIN SELECT * FROM bills WHERE due_on<CURRENT_DATE AND amount_paid<charge;
CREATE OR REPLACE PROCEDURE pr_refresh_receivables() LANGUAGE plpgsql AS $$
BEGIN INSERT INTO receivable_snapshot SELECT CURRENT_DATE,COALESCE(sum(charge-amount_paid),0) FROM bills WHERE amount_paid<charge ON CONFLICT(snapshot_date) DO UPDATE SET total_due=EXCLUDED.total_due; END $$;
CALL pr_refresh_receivables();
-- Schedule daily at 00:30: CALL water_q7.pr_refresh_receivables().
SELECT * FROM v_overdue_bills; SELECT * FROM receivable_snapshot;